// One HTTP call regardless of row count, and the row count travels with the
// text so the approval envelope's scope can state how much was summarised.
const rows = $input.all().map(i => i.json).filter(r => r && r.prompt);
const text = rows.length
  ? rows.map((r, n) => (n + 1) + '. ' + r.prompt + ' -> ' + String(r.answer).replace(/\s+/g, ' ').slice(0, 400)).join('\n')
  : '(no W4 results in the last day)';
return [{ json: { rows: rows.length, text } }];

// The FINAL parameters, which is what the envelope's hash has to cover.  If
// this text can still change after the hash is taken, the hash proves nothing.
const msg = (($json.choices || [])[0] || {}).message || {};
const summary = (msg.content || '').trim();
if (!summary) {
  throw new Error('the model returned no summary: ' + JSON.stringify($json).slice(0, 300));
}
return [{ json: { summary: summary.slice(0, 2000), rows: $('Collect the day').first().json.rows } }];

// The only output a human should read after a request run: what is waiting,
// who can decide it, and the exact command that decides it.
const r = $json;
return [{
  json: {
    status: 'awaiting_approval',
    action_id: r.action_id,
    approver: r.approver_subject,
    recipient: r.recipient,
    expires_at: r.expires_at,
    decide_with: 'aistack samples approve ' + r.action_id + '   (add --reject to refuse)',
  },
}];
